module tb;
  reg clk=0, rst=0, data=0;
  wire flag;
  TopModule dut(.clk(clk), .rst(rst), .data(data), .flag(flag));
  always #5 clk = ~clk;

  task step(input bit d);
    begin
      data = d;
      @(posedge clk);
      "'$display("t=%0t data=%0b state=%0d nstate=%0d flag=%0b", $time, data, dut.state, dut.nstate, flag);
    end
  endtask

  initial begin
    rst = 0; data = 0;
    repeat (2) @(posedge clk);
    rst = 1;
    // stream 10110111, expect two pulses delayed by one cycle after each detection
    step(1); step(0); step(1); step(1); step(0); step(1); step(1); step(1);
    @(posedge clk);
    $finish;
  end
endmodule
EOF
